insert into public.site_settings(key,value) values ('site','{"brand":"Hax Estúdio","signature":"Leanderson · Hax Estúdio","headline":"O dia passa.\nO que sentimos fica.","intro":"Filmes de casamento para reviver o que faz a sua história ser única.","films_title":"O amor acontece.\nA gente guarda.","films_intro":"Cada casal tem um jeito de viver o dia. Cada filme encontra o seu próprio ritmo.","experience_title":"Vocês vivem.\nNós contamos.","experience_intro":"Do primeiro encontro à última cena, um filme construído a partir de vocês.","step1_title":"Antes do grande dia","step1_text":"Uma conversa para conhecer a história, os planos e aquilo que importa para vocês.","step2_title":"Durante o casamento","step2_text":"Um olhar atento para os encontros, os gestos e os momentos que acontecem naturalmente.","step3_title":"Para reviver depois","step3_text":"Imagem, som e edição reunidos em uma memória que vocês possam sentir outra vez.","calendar_title":"Tem uma data\nem mente?","calendar_text":"Encontre o seu dia e conte seus planos. A consulta inicia nossa conversa; a reserva é confirmada com a contratação.","packages_title":"Nossas\ncoleções.","packages_intro":"Encontre o formato que combina com a sua história.","faq_title":"Vamos tirar\nsuas dúvidas.","footer_text":"Histórias que merecem ficar.","whatsapp":"5544991855451","email":"","instagram":"","region":"","hero_cover":"/assets/covers/T0VN2ykadeg.jpg","hero_video":"https://www.youtube.com/watch?v=T0VN2ykadeg","about_title":"A sua história,\ncom o nosso olhar.","about_photo":"/assets/leanderson.png","about":"Meu trabalho é transformar o casamento em um filme que pareça verdadeiro para vocês. Sem excesso de poses, sem pressa e sem transformar cada momento em uma produção. A câmera acompanha o dia com cuidado, enquanto a edição organiza tudo em uma memória que faça sentido muitos anos depois.","contact_title":"Vamos contar\na sua história?","contact_text":"Conte um pouco sobre vocês e sobre o dia que estão imaginando. Vamos conversar sobre o filme do seu casamento.","seo_title":"Hax Estúdio | Filmes de casamento","seo_description":"Filmes de casamento e pré-wedding por Leanderson, Hax Estúdio. Conheça nossas histórias e consulte sua data.","privacy_email":"","meeting_url":""}'::jsonb) on conflict(key) do nothing;
insert into public.site_settings(key,value) values ('theme','{"background":"#11120f","surface":"#1c1d19","text":"#f0ece4","muted":"#b3b3a7","accent":"#c9b58e","heading_font":"Cormorant Garamond","body_font":"Manrope","heading_scale":1,"body_size":16}'::jsonb) on conflict(key) do nothing;
